  verify("before");const auto slots=d.palette().slots;const int columns=d.palette().columns;const auto it=std::find_if(slots.begin(),slots.end(),[](int id){return id!=0;});const auto first=std::size_t(it-slots.begin());
  if(operation=="gradient-colors"||operation=="gradient-colors-hue")d.gradientPaletteColors(operation=="gradient-colors-hue");
  else if(operation=="update")d.updatePaletteColor(1,0xff3c2814);
  else if(operation=="rename")d.renamePaletteColor(1,U" renamed ");
  else if(operation=="reverse"||operation=="reverse-selected")d.reversePaletteColors();
  else if(operation=="sort")d.sortPaletteColors(Document::PaletteSortMode::Red,false);
