  std::string phase="import";const auto verify=[&](const Document& candidate){check(candidate.frame().id==expected.frame().id&&candidate.layer().id==expected.layer().id,"Repaired links preserve active identities");check(candidate.timeline().diagnoseLinks().empty(),"Imported malformed links are fully repaired");check(candidate.timeline().state().tilesets.size()==expected.timeline().state().tilesets.size(),"Repair preserves all resource identities");for(std::size_t i=0;i<expected.timeline().state().tilesets.size();++i){const auto& a=candidate.timeline().state().tilesets[i];const auto& b=expected.timeline().state().tilesets[i];check(a.id==b.id&&a.tileIds==b.tileIds&&a.pixels==b.pixels,"Repair preserves exact resource pixels and tile IDs");}check(candidate.timeline().state().cels.size()==expected.timeline().state().cels.size(),"Repaired links preserve all slots");for(const auto& layer:expected.timeline().state().layers)for(const auto& frame:expected.timeline().state().frames){const auto* actual=candidate.timeline().findCel(layer.id,frame.id);const auto* wanted=expected.timeline().findCel(layer.id,frame.id);check(actual&&wanted&&bool(actual->linkedCelId)==bool(wanted->linkedCelId),"Legacy input-order link break and flattening");if(actual->linkedCelId){const auto* a=candidate.timeline().findCelById(*actual->linkedCelId);const auto* b=expected.timeline().findCelById(*wanted->linkedCelId);check(a&&b&&a->frameId==b->frameId&&a->layerId==b->layerId,"Legacy repaired root identity");}const auto a=candidate.timeline().resolveSurface(actual->id),b=expected.timeline().resolveSurface(wanted->id);check(a.surface&&b.surface&&(phase=="undo"?sameWorld(*a.surface,*b.surface):(a.surface->width==b.surface->width&&a.surface->height==b.surface->height&&a.surface->offsetX==b.surface->offsetX&&a.surface->offsetY==b.surface->offsetY&&a.surface->pixels==b.surface->pixels)),(name+" phase="+phase+" frame="+frame.id+" actual="+std::to_string(a.surface->width)+"x"+std::to_string(a.surface->height)+" expected="+std::to_string(b.surface->width)+"x"+std::to_string(b.surface->height)).c_str());check(a.source->opacity==b.source->opacity&&a.source->zIndex==b.source->zIndex&&sameText(a.source->text,b.source->text)&&sameGrid(a.source->tilemap,b.source->tilemap)&&a.source->freeTiles==b.source->freeTiles,(name+" metadata frame="+frame.id).c_str());}};
  verify(d);check(d.historyPosition()==0,"Malformed link import creates no edit history");if(kind=="free-tile"&&!fallback&&active!=0){const auto resolved=d.timeline().resolveSurface(d.cel().id);check(resolved.source->freeTiles&&!resolved.source->freeTiles->instances.empty()&&std::any_of(resolved.surface->pixels.begin(),resolved.surface->pixels.end(),[](auto p){return p!=0;}),"Approved missing-raster repair retains instances and restores their display");}for(bool recovery:{false,true}){phase=recovery?"recovery":"save";auto saved=recovery?encodeRecoveryProject(d):encodeEditableProject(d);verify(createEditableDocument(prepareEditableImport(readProjectManifest(saved.bytes))));}
  phase="undo";if(kind=="raster"){const int x=std::clamp(d.activeSurfaceIfPresent()->offsetX,0,d.width()-1),y=std::clamp(d.activeSurfaceIfPresent()->offsetY,0,d.height()-1);d.beginStroke({x,y},0xffabcdef);check(d.commitStroke(),"Repaired active Cel remains editable");d.undo();verify(d);d.redo();check(raster::readWorld(*d.activeSurfaceIfPresent(),x,y)==0xffabcdef,"Repaired Cel edit redo");}else{d.addFrame(true);check(d.timeline().state().frames.size()==4,"Repaired structured Cel duplicable");d.undo();verify(d);d.redo();check(d.timeline().state().frames.size()==4,"Repaired structured Cel duplicate redo");}
